  --container-narrow: 1000px;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bloom-milk);
  color: var(--deep-petal);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  color: var(--deep-petal);
  margin: 0;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

p {
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

img, svg {
  display: block;
  max-width: 100%;
}

button {
  font-family: inherit;
  cursor: pointer;
}

/* === Reusable layout primitives === */
.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

.container-narrow {
  width: 100%;
  max-width: var(--container-narrow);
  margin: 0 auto;
  padding: 0 24px;
}

.eyebrow {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--lumi-coral);
  display: inline-block;
}

.section {
  position: relative;
  width: 100%;
}

/* === Buttons === */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 16px;
  padding: 14px 28px;
  border-radius: var(--radius-pill);
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform 220ms cubic-bezier(.2,.7,.2,1), background 220ms ease, color 220ms ease, box-shadow 220ms ease, border-color 220ms ease;
  text-decoration: none;
  white-space: nowrap;
  line-height: 1;
}

.btn:hover {
  transform: translateY(-2px) scale(1.02);
}

.btn-primary {
  background: var(--lumi-coral);
  color: #fff;
  box-shadow: 0 6px 18px rgba(255, 111, 94, 0.28);
}

.btn-primary:hover {
  background: #ff5a47;
  box-shadow: 0 10px 26px rgba(255, 111, 94, 0.36);
}

.btn-secondary {
  background: transparent;
  color: var(--aqua-bloom);
  border-color: var(--aqua-bloom);
}

.btn-secondary:hover {
  background: var(--aqua-bloom);
  color: #fff;
}

.btn-light {
  background: #fff;
  color: var(--lumi-coral);
}

.btn-light:hover {
  background: var(--sunshine-butter);
  color: var(--deep-petal);
}

.btn-ghost-light {
  background: transparent;
  color: #fff;
  border-color: #fff;
}

.btn-ghost-light:hover {
  background: rgba(255, 255, 255, 0.18);
  color: #fff;
}

.btn-dark {
  background: var(--deep-petal);
  color: var(--bloom-milk);
}

.btn-dark:hover {
  background: #1c2622;
}

/* === Reveal animations (IntersectionObserver targets) === */
.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 720ms cubic-bezier(.2,.7,.2,1), transform 720ms cubic-bezier(.2,.7,.2,1);
  will-change: opacity, transform;
}

.reveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.reveal-fade {
  opacity: 0;
  transition: opacity 800ms ease;
}

.reveal-fade.is-visible {
  opacity: 1;
}

/* stagger delays */
.reveal[data-d="1"] { transition-delay: 80ms; }
.reveal[data-d="2"] { transition-delay: 160ms; }
.reveal[data-d="3"] { transition-delay: 240ms; }
.reveal[data-d="4"] { transition-delay: 320ms; }
.reveal[data-d="5"] { transition-delay: 400ms; }
.reveal[data-d="6"] { transition-delay: 480ms; }
.reveal[data-d="7"] { transition-delay: 560ms; }

/* === On-load entrance for hero (no observer needed) === */
@keyframes lb-rise {
  from { opacity: 0; transform: translateY(28px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes lb-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes lb-pop {
  0% { opacity: 0; transform: scale(0.85); }
  60% { transform: scale(1.04); }
  100% { opacity: 1; transform: scale(1); }
}
@keyframes lb-bloom-rotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
@keyframes lb-bloom-breathe {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.04); }
}
@keyframes lb-pulse-coral {
  0%, 100% { box-shadow: 0 6px 18px rgba(255,111,94,0.28), 0 0 0 0 rgba(255,111,94,0.45); }
  50% { box-shadow: 0 6px 18px rgba(255,111,94,0.28), 0 0 0 18px rgba(255,111,94,0); }
}
@keyframes lb-marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
@keyframes lb-shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
@keyframes lb-drift {
  0%, 100% { transform: translateY(0px) translateX(0px); }
  50% { transform: translateY(-10px) translateX(6px); }
}

.entrance-rise {
  animation: lb-rise 800ms cubic-bezier(.2,.7,.2,1) both;
}
.entrance-rise[data-d="1"] { animation-delay: 100ms; }
.entrance-rise[data-d="2"] { animation-delay: 220ms; }
.entrance-rise[data-d="3"] { animation-delay: 340ms; }
.entrance-rise[data-d="4"] { animation-delay: 460ms; }
.entrance-rise[data-d="5"] { animation-delay: 580ms; }

.entrance-pop {
  animation: lb-pop 1100ms cubic-bezier(.2,.7,.2,1) both;
  animation-delay: 300ms;
}

/* === Header / Nav === */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 80;
  background: rgba(255, 248, 244, 0.88);
  backdrop-filter: saturate(160%) blur(10px);
  -webkit-backdrop-filter: saturate(160%) blur(10px);
  border-bottom: 1px solid rgba(45, 58, 53, 0.06);
}

.site-nav__inner {
  max-width: var(--container);
  margin: 0 auto;
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.site-nav__brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-accent);
  font-size: 20px;
  color: var(--deep-petal);
}

.site-nav__brand-mark {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, var(--sunshine-butter), var(--lumi-coral) 70%);
  box-shadow: inset 0 0 0 2px var(--bloom-milk);
  position: relative;
  flex-shrink: 0;
  animation: lb-bloom-breathe 5s ease-in-out infinite;
}

.site-nav__links {
  display: flex;
  align-items: center;
  gap: 28px;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 15px;
}

.site-nav__link {
  position: relative;
  color: var(--deep-petal);
  padding: 6px 2px;
  transition: color 200ms ease;
}

.site-nav__link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 2px;
  background: var(--lumi-coral);
  border-radius: 2px;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 280ms cubic-bezier(.2,.7,.2,1);
}

.site-nav__link:hover { color: var(--lumi-coral); }
.site-nav__link:hover::after,
.site-nav__link.is-active::after { transform: scaleX(1); }
.site-nav__link.is-active { color: var(--lumi-coral); }

.site-nav__cta {
  font-size: 14px;
  padding: 10px 18px;
}

@media (max-width: 720px) {
  .site-nav__links { gap: 16px; font-size: 13px; }
  .site-nav__cta { display: none; }
  .site-nav__inner { padding: 12px 18px; }
}

/* === Footer === */
.site-footer {
  background: var(--deep-petal);
  color: var(--bloom-milk);
  padding: 64px 0 32px;
  margin-top: 0;
}

.site-footer__grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr;
  gap: 40px;
  align-items: start;
}

.site-footer__brand {
  font-family: var(--font-accent);
  font-size: 28px;
  color: var(--bloom-milk);
  display: inline-flex;
  align-items: center;
  gap: 12px;
}

.site-footer__tag {
  font-family: var(--font-body);
  font-size: 15px;
  color: rgba(255, 248, 244, 0.72);
  margin-top: 12px;
  max-width: 320px;
  line-height: 1.6;
}

.site-footer__col h4 {
  font-family: var(--font-accent);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: var(--sunshine-butter);
  margin-bottom: 16px;
}

.site-footer__col ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 15px;
  color: rgba(255, 248, 244, 0.82);
}

.site-footer__col a {
  transition: color 200ms ease;
}

.site-footer__col a:hover {
  color: var(--lumi-coral);
}

.site-footer__bottom {
  margin-top: 48px;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 248, 244, 0.10);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: rgba(255, 248, 244, 0.55);
  flex-wrap: wrap;
  gap: 12px;
}

@media (max-width: 880px) {
  .site-footer__grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 520px) {
  .site-footer__grid { grid-template-columns: 1fr; }
  .site-footer { padding: 48px 0 24px; }
}

