import React from 'react';

export function BloomIllustration({ size = 480, className = '' }) {
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 480 480"
      role="img"
      aria-label="Lumi & Bloom flower mark"
    >
      <defs>
        <radialGradient id="bloom-core" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#FFF8F4" />
          <stop offset="60%" stopColor="#FFE566" />
          <stop offset="100%" stopColor="#FFCBA4" />
        </radialGradient>
        <radialGradient id="bloom-petal" cx="50%" cy="35%" r="60%">
          <stop offset="0%" stopColor="#FF9685" />
          <stop offset="100%" stopColor="#FF6F5E" />
        </radialGradient>
      </defs>

      <g className="bloom-petal-ring" style={{ transformOrigin: '240px 240px' }}>
        {Array.from({ length: 10 }).map((_, i) => {
          const angle = (360 / 10) * i;
          return (
            <ellipse
              key={i}
              cx="240"
              cy="110"
              rx="42"
              ry="92"
              fill="url(#bloom-petal)"
              opacity="0.92"
              transform={`rotate(${angle} 240 240)`}
            />
          );
        })}
      </g>

      <g className="bloom-leaf-ring" style={{ transformOrigin: '240px 240px' }}>
        {Array.from({ length: 5 }).map((_, i) => {
          const angle = (360 / 5) * i + 36;
          return (
            <ellipse
              key={i}
              cx="240"
              cy="80"
              rx="20"
              ry="44"
              fill="#A8E6CF"
              opacity="0.85"
              transform={`rotate(${angle} 240 240)`}
            />
          );
        })}
      </g>

      <circle cx="240" cy="240" r="92" fill="url(#bloom-core)" />
      <circle cx="240" cy="240" r="92" fill="none" stroke="#FFF8F4" strokeWidth="3" />

      {/* Sparkles */}
      <g fill="#FFE566">
        <circle cx="110" cy="160" r="6" />
        <circle cx="380" cy="320" r="5" />
        <circle cx="380" cy="120" r="4" />
        <circle cx="120" cy="360" r="4" />
      </g>
    </svg>
  );
}

export function BrandMark({ size = 32 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" role="img" aria-label="Lumi & Bloom mark">
      <defs>
        <radialGradient id="brand-mark-grad" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#FFE566" />
          <stop offset="100%" stopColor="#FF6F5E" />
        </radialGradient>
      </defs>
      {Array.from({ length: 8 }).map((_, i) => {
        const angle = (360 / 8) * i;
        return (
          <ellipse
            key={i}
            cx="24"
            cy="9"
            rx="5"
            ry="11"
            fill="#FFCBA4"
            transform={`rotate(${angle} 24 24)`}
          />
        );
      })}
      <circle cx="24" cy="24" r="9" fill="url(#brand-mark-grad)" />
    </svg>
  );
}

