import React from 'react';

/* Two hands cupping a blooming flower — brand page header */
export function HandsAndBloom({ size = 200 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 200 200" role="img" aria-label="Two hands cupping a flower">
      <g fill="none" stroke="#2D3A35" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        {/* Bloom petals */}
        <g fill="#A8E6CF" stroke="#2D3A35">
          {Array.from({ length: 6 }).map((_, i) => {
            const angle = (360 / 6) * i;
            return (
              <ellipse
                key={i}
                cx="100"
                cy="55"
                rx="14"
                ry="26"
                transform={`rotate(${angle} 100 80)`}
              />
            );
          })}
        </g>
        <circle cx="100" cy="80" r="11" fill="#FFE566" stroke="#2D3A35" />
        {/* Stem */}
        <path d="M100 92 Q 100 120 100 140" />
        <path d="M100 118 Q 88 112 78 122" fill="#A8E6CF" />
        {/* Hands - left */}
        <path d="M30 140 Q 50 110 78 130 L 88 158 Q 70 174 50 170 Z" fill="#FFCBA4" />
        {/* Hand details - left */}
        <path d="M50 145 Q 58 138 66 142" stroke="#2D3A35" fill="none" />
        <path d="M55 155 Q 62 148 70 152" stroke="#2D3A35" fill="none" />
        {/* Hands - right */}
        <path d="M170 140 Q 150 110 122 130 L 112 158 Q 130 174 150 170 Z" fill="#FFCBA4" />
        <path d="M150 145 Q 142 138 134 142" stroke="#2D3A35" fill="none" />
        <path d="M145 155 Q 138 148 130 152" stroke="#2D3A35" fill="none" />
      </g>
    </svg>
  );
}

/* Globe wrapped in botanical vine — sustainability header */
export function GlobeVine({ size = 200 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 200 200" role="img" aria-label="Globe wrapped in a leafy vine">
      <defs>
        <radialGradient id="globe-grad" cx="40%" cy="40%" r="60%">
          <stop offset="0%" stopColor="#EDF6F9" />
          <stop offset="100%" stopColor="#A8E6CF" />
        </radialGradient>
      </defs>
      <circle cx="100" cy="100" r="70" fill="url(#globe-grad)" stroke="#2D3A35" strokeWidth="2.5" />
      {/* Continents */}
      <g fill="#2D3A35" opacity="0.85">
        <path d="M62 80 Q 70 70 82 76 Q 90 84 84 96 Q 74 100 66 92 Z" />
        <path d="M104 70 Q 116 64 128 76 L 122 86 Q 110 88 104 80 Z" />
        <path d="M76 116 Q 88 110 100 118 Q 110 128 102 138 Q 88 142 78 132 Z" />
        <path d="M122 120 Q 134 116 142 124 L 138 134 Q 128 132 122 128 Z" />
      </g>
      {/* Equator-ish line */}
      <path d="M30 100 Q 100 122 170 100" fill="none" stroke="#2D3A35" strokeWidth="1.5" opacity="0.5" />
      {/* Vine */}
      <g stroke="#2D3A35" strokeWidth="2.5" fill="none" strokeLinecap="round">
        <path d="M20 60 Q 100 30 180 60" />
        <path d="M180 140 Q 100 170 20 140" />
      </g>
      {/* Leaves on vine */}
      <g fill="#A8E6CF" stroke="#2D3A35" strokeWidth="1.5">
        <ellipse cx="50" cy="48" rx="9" ry="5" transform="rotate(-30 50 48)" />
        <ellipse cx="100" cy="32" rx="10" ry="5" transform="rotate(0 100 32)" />
        <ellipse cx="150" cy="48" rx="9" ry="5" transform="rotate(30 150 48)" />
        <ellipse cx="50" cy="154" rx="9" ry="5" transform="rotate(30 50 154)" />
        <ellipse cx="100" cy="170" rx="10" ry="5" />
        <ellipse cx="150" cy="154" rx="9" ry="5" transform="rotate(-30 150 154)" />
      </g>
      {/* Coral tips on vine */}
      <g fill="#FF6F5E">
        <circle cx="20" cy="60" r="4" />
        <circle cx="180" cy="60" r="4" />
        <circle cx="180" cy="140" r="4" />
        <circle cx="20" cy="140" r="4" />
      </g>
    </svg>
  );
}

/* Open envelope with bloom emerging — contact header */
export function EnvelopeBloom({ size = 280 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 320 320" role="img" aria-label="Open envelope with a flower emerging">
