  display: grid;
  grid-template-columns: 7fr 5fr;
  align-items: center;
  gap: 32px;
  position: relative;
  z-index: 1;
}
.contact-header__eyebrow { color: var(--lumi-coral); }
.contact-header__h1 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(36px, 6vw, 68px);
  line-height: 1.05;
  margin-top: 16px;
  color: var(--deep-petal);
}
.contact-header__h1 .accent { color: var(--lumi-coral); }
.contact-header__sub {
  margin-top: 24px;
  font-size: 18px;
  color: rgba(45, 58, 53, 0.7);
  line-height: 1.65;
  max-width: 520px;
}
.contact-header__art {
  position: relative;
  height: 320px;
  display: flex;
  align-items: center;
