/* ============================================================
   Generic section base
   ============================================================ */
section { position: relative; }

.sec-pad-lg { padding: 100px 0; }
.sec-pad-md { padding: 80px 0; }
.sec-pad-sm { padding: 56px 0; }

@media (max-width: 720px) {
  .sec-pad-lg { padding: 64px 0; }
  .sec-pad-md { padding: 56px 0; }
  .sec-pad-sm { padding: 40px 0; }
}

/* ============================================================
   HOME — Hero (home-section-1)
   ============================================================ */
.home-hero {
  background: var(--glow-peach);
  padding: 100px 0 56px;
  overflow: visible;
  position: relative;
  z-index: 2;
}

.home-hero__inner {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  min-height: 480px;
  gap: 32px;
  position: relative;
}

.home-hero__text {
  position: relative;
  z-index: 3;
  max-width: 560px;
}

.home-hero__eyebrow { color: var(--lumi-coral); }

.home-hero__headline {
  font-size: clamp(40px, 6vw, 68px);
  font-weight: 800;
  line-height: 1.05;
  margin: 16px 0 0;
  color: var(--deep-petal);
}

.home-hero__headline .accent {
  color: var(--lumi-coral);
  position: relative;
  display: inline-block;
}

.home-hero__sub {
  margin-top: 20px;
  font-size: 18px;
  line-height: 1.65;
  color: rgba(45, 58, 53, 0.8);
  max-width: 480px;
}

.home-hero__ctas {
  margin-top: 32px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.home-hero__btn-primary { animation: lb-pulse-coral 3.6s ease-in-out infinite; }

.home-hero__bloom {
  position: absolute;
  bottom: -120px;
  left: 52%;
  width: 520px;
  height: 520px;
  pointer-events: none;
  z-index: 1;
}

.home-hero__bloom .bloom-petal-ring {
  animation: lb-bloom-rotate 60s linear infinite;
  transform-origin: 240px 240px;
}
.home-hero__bloom .bloom-leaf-ring {
  animation: lb-bloom-rotate 90s linear infinite reverse;
  transform-origin: 240px 240px;
}

.home-hero__sparkles {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}

.home-hero__spark {
  position: absolute;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--sunshine-butter);
  filter: drop-shadow(0 0 6px rgba(255, 229, 102, 0.6));
  animation: lb-drift 6s ease-in-out infinite;
}
.home-hero__spark:nth-child(1) { top: 12%; left: 8%; animation-delay: 0s; }
.home-hero__spark:nth-child(2) { top: 30%; right: 12%; animation-delay: 1s; background: var(--lumi-coral); }
.home-hero__spark:nth-child(3) { bottom: 22%; left: 14%; animation-delay: 2s; background: var(--aqua-bloom); }
.home-hero__spark:nth-child(4) { top: 50%; right: 24%; animation-delay: 3s; background: #fff; }

@media (max-width: 880px) {
  .home-hero__inner { grid-template-columns: 1fr; min-height: 380px; text-align: center; }
  .home-hero__text { margin: 0 auto; }
  .home-hero__sub { margin-left: auto; margin-right: auto; }
  .home-hero__ctas { justify-content: center; }
  .home-hero__bloom { position: relative; bottom: auto; left: auto; width: 280px; height: 280px; margin: 24px auto -100px; }
}

/* ============================================================
   HOME — Gallery (home-section-2)
   ============================================================ */
.home-gallery {
  background: var(--bloom-milk);
  padding: 140px 0 80px;
  position: relative;
  z-index: 1;
}

.home-gallery__intro {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 48px;
}

.home-gallery__intro .eyebrow { color: var(--aqua-bloom); }

.home-gallery__headline {
  font-size: clamp(26px, 3.4vw, 38px);
  font-weight: 700;
  color: var(--deep-petal);
  margin-top: 8px;
}

.home-gallery__sub {
  margin-top: 12px;
  font-size: 17px;
  color: rgba(45, 58, 53, 0.7);
}

.home-gallery__grid {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  align-items: start;
}

.home-gallery__card {
  background: #fff;
  border-radius: 20px;
  box-shadow: var(--shadow-card);
  overflow: visible;
  position: relative;
  transition: transform 360ms cubic-bezier(.2,.7,.2,1), box-shadow 360ms ease;
}

.home-gallery__card:hover {
  transform: translateY(-8px) rotate(-0.4deg);
  box-shadow: var(--shadow-card-hover);
}

.home-gallery__card .ribbon {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 6px;
  background: var(--glow-peach);
  border-radius: 20px 20px 0 0;
  z-index: 1;
}

.home-gallery__image {
  position: relative;
  aspect-ratio: 4 / 3;
  background: linear-gradient(135deg, rgba(255, 203, 164, 0.45), rgba(255, 248, 244, 0.8));
  border-radius: 20px 20px 0 0;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.home-gallery__image svg {
  width: 86%;
  height: 86%;
  transition: transform 600ms cubic-bezier(.2,.7,.2,1);
}
.home-gallery__card:hover .home-gallery__image svg {
  transform: scale(1.05) rotate(-1deg);
}

.home-gallery__badge {
  position: absolute;
  top: -8px;
  right: -8px;
  background: var(--sunshine-butter);
  color: var(--deep-petal);
  font-family: var(--font-accent);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  text-align: center;
  line-height: 1;
  padding: 6px;
  z-index: 3;
  box-shadow: 0 6px 14px rgba(45, 58, 53, 0.12);
  transform: rotate(-8deg);
  transition: transform 320ms cubic-bezier(.2,.7,.2,1);
}

.home-gallery__card:hover .home-gallery__badge { transform: rotate(0deg) scale(1.05); }

.home-gallery__body { padding: 18px 18px 22px; }
.home-gallery__title { font-family: var(--font-heading); font-weight: 700; font-size: 19px; color: var(--deep-petal); }
.home-gallery__meta {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.10em;
  color: var(--aqua-bloom);
  text-transform: uppercase;
  margin-top: 4px;
}
.home-gallery__desc {
  margin-top: 8px;
  font-size: 14.5px;
  color: rgba(45, 58, 53, 0.75);
  line-height: 1.55;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.home-gallery__cta-row {
  margin-top: 48px;
  display: flex;
  justify-content: center;
}

@media (max-width: 980px) {
  .home-gallery__grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 560px) {
  .home-gallery__grid { grid-template-columns: 1fr; }
  .home-gallery { padding: 120px 0 64px; }
}

/* ============================================================
   HOME — Stats (home-section-3)
   ============================================================ */
.home-stats {
  background: var(--petal-mint);
  padding: 64px 0;
}
.home-stats__intro { text-align: center; }
.home-stats__intro .eyebrow { color: rgba(45, 58, 53, 0.6); }
.home-stats__headline {
  font-size: clamp(24px, 2.8vw, 34px);
  font-weight: 700;
  margin-top: 6px;
  color: var(--deep-petal);
}
.home-stats__row {
  max-width: var(--container);
  margin: 40px auto 0;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  position: relative;
}
.home-stats__cell {
  text-align: center;
  position: relative;
  padding: 0 16px;
}
.home-stats__cell + .home-stats__cell::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 56px;
  background: var(--aqua-bloom);
  opacity: 0.7;
}
.home-stats__num {
  font-family: var(--font-accent);
  font-size: clamp(40px, 5.4vw, 68px);
  line-height: 1;
  color: var(--deep-petal);
}
.home-stats__num .star { color: var(--sunshine-butter); }
.home-stats__desc {
  font-size: 14.5px;
  color: rgba(45, 58, 53, 0.78);
  margin: 10px auto 0;
  max-width: 200px;
}
@media (max-width: 720px) {
  .home-stats__row { grid-template-columns: repeat(2, 1fr); row-gap: 32px; }
  .home-stats__cell + .home-stats__cell::before { display: none; }
}

/* ============================================================
   HOME — Testimonials (home-section-4)
   ============================================================ */
.home-test {
  background: var(--soft-cloud);
  padding: 80px 0;
}
.home-test__head { max-width: var(--container); margin: 0 auto; padding: 0 24px; }
.home-test__eyebrow { color: var(--lumi-coral); }
.home-test__headline {
  font-size: clamp(26px, 3.4vw, 38px);
  font-weight: 700;
  margin-top: 8px;
  color: var(--deep-petal);
  max-width: 560px;
}

.home-test__cards-wrap {
  position: relative;
  max-width: var(--container);
  margin: 32px auto 0;
  padding: 0 24px;
}

.home-test__quote-mark {
  position: absolute;
  top: -42px;
  left: 12px;
  font-family: var(--font-accent);
  font-size: 160px;
  color: var(--lumi-coral);
  line-height: 1;
  opacity: 0.95;
  pointer-events: none;
  z-index: 0;
  user-select: none;
}

.home-test__cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
  position: relative;
  z-index: 1;
}

.home-test__card {
  background: var(--glow-peach);
  border-radius: 22px;
  padding: 28px;
  position: relative;
  transition: transform 360ms cubic-bezier(.2,.7,.2,1);
}
.home-test__card:hover { transform: translateY(-6px) rotate(0.6deg); }
.home-test__card-q {
  font-family: var(--font-accent);
  font-size: 32px;
  color: var(--lumi-coral);
  line-height: 1;
  margin-bottom: 8px;
}
.home-test__card-quote {
  font-style: italic;
  font-size: 15.5px;
  line-height: 1.65;
  color: var(--deep-petal);
}
.home-test__card-name {
  font-family: var(--font-heading);
  font-weight: 800;
  margin-top: 16px;
  color: var(--deep-petal);
  font-size: 17px;
}
.home-test__card-tag {
  display: inline-block;
  margin-top: 8px;
  background: #fff;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--aqua-bloom);
  padding: 4px 10px;
  border-radius: 20px;
}

@media (max-width: 880px) {
  .home-test__cards { grid-template-columns: 1fr; }
  .home-test__quote-mark { font-size: 110px; top: -32px; }
}

/* ============================================================
   HOME — CTA (home-section-5) — also reused as full-bleed coral CTA
   ============================================================ */
.cta-coral {
  background: var(--lumi-coral);
  color: #fff;
  padding: 96px 0;
  position: relative;
  overflow: hidden;
  text-align: center;
}
.cta-coral .container { position: relative; z-index: 1; }
.cta-coral__eyebrow { color: rgba(255, 255, 255, 0.85); }
.cta-coral__headline {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(36px, 6vw, 64px);
  color: #fff;
  line-height: 1.05;
  max-width: 640px;
  margin: 8px auto 0;
}
.cta-coral__headline .accent { color: var(--sunshine-butter); }
.cta-coral__sub {
  margin: 20px auto 0;
  font-size: 17px;
  color: rgba(255, 255, 255, 0.9);
  max-width: 460px;
  line-height: 1.6;
}
.cta-coral__btns {
  margin-top: 36px;
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ============================================================
   BRAND — Page header (brand-section-1)
   ============================================================ */
.brand-header {
  background: var(--bloom-milk);
  padding: 96px 0 72px;
  text-align: center;
}
.brand-header__art {
  margin: 0 auto 32px;
  width: 180px;
  animation: lb-drift 8s ease-in-out infinite;
}
.brand-header__eyebrow { color: var(--aqua-bloom); }
.brand-header__headline {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(32px, 5vw, 56px);
  line-height: 1.15;
  max-width: 760px;
  margin: 16px auto 16px;
  color: var(--deep-petal);
}
.brand-header__sub {
  font-size: 18px;
  line-height: 1.65;
  color: rgba(45, 58, 53, 0.75);
  max-width: 560px;
  margin: 0 auto;
}

/* ============================================================
   BRAND — Story block (brand-section-2)
   ============================================================ */
.brand-story {
  background: var(--glow-peach);
  padding: 80px 0;
}
.brand-story__grid {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 55fr 45fr;
  gap: 56px;
  align-items: center;
}
.brand-story__left { position: relative; }
.brand-story__pullquote {
  font-family: var(--font-accent);
  font-size: clamp(36px, 5.6vw, 76px);
  color: var(--lumi-coral);
  line-height: 1.05;
  margin-left: -24px;
  position: relative;
}
.brand-story__eyebrow {
  display: inline-block;
  margin-top: 32px;
  color: var(--deep-petal);
}
.brand-story__h2 {
  font-size: clamp(24px, 3vw, 34px);
  font-weight: 700;
  margin-top: 12px;
  color: var(--deep-petal);
}
.brand-story__body {
  font-size: 17px;
  line-height: 1.7;
  color: var(--deep-petal);
}
@media (max-width: 880px) {
  .brand-story__grid { grid-template-columns: 1fr; gap: 32px; }
  .brand-story__pullquote { margin-left: 0; }
}

/* ============================================================
   BRAND — Values grid (brand-section-3)
   ============================================================ */
.brand-values {
  background: var(--petal-mint);
  padding: 80px 0;
}
.brand-values__head { text-align: center; max-width: 700px; margin: 0 auto; padding: 0 24px; }
.brand-values__head .eyebrow { color: var(--deep-petal); }
.brand-values__head h2 {
  font-size: clamp(26px, 3.4vw, 36px);
  font-weight: 700;
  margin-top: 8px;
  color: var(--deep-petal);
}
.brand-values__head p {
  font-size: 17px;
  color: rgba(45, 58, 53, 0.78);
  margin-top: 16px;
}
.brand-values__grid {
  max-width: 1100px;
  margin: 40px auto 0;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.brand-values__card {
  background: var(--bloom-milk);
  border-radius: 24px;
  padding: 32px;
  box-shadow: 0 4px 16px rgba(45, 58, 53, 0.08);
  transition: transform 360ms cubic-bezier(.2,.7,.2,1), box-shadow 360ms ease;
}
.brand-values__card:hover {
  transform: translateY(-6px);
  box-shadow: 0 12px 28px rgba(45, 58, 53, 0.12);
}
.brand-values__icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--sunshine-butter);
  display: grid;
  place-items: center;
  margin-bottom: 20px;
  transition: transform 360ms cubic-bezier(.2,.7,.2,1);
}
.brand-values__card:hover .brand-values__icon { transform: rotate(8deg) scale(1.06); }
.brand-values__card h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 20px;
  color: var(--deep-petal);
}
.brand-values__card p {
  margin-top: 10px;
  font-size: 15.5px;
  line-height: 1.6;
  color: rgba(45, 58, 53, 0.78);
}
.brand-values__cta {
  margin-top: 40px;
  text-align: center;
}
@media (max-width: 720px) {
  .brand-values__grid { grid-template-columns: 1fr; }
}

/* ============================================================
   BRAND — Timeline (brand-section-4)
   ============================================================ */
.brand-timeline {
  background: var(--soft-cloud);
  padding: 88px 0;
}
.brand-timeline__head {
  max-width: 1000px;
  margin: 0 auto;
  padding: 0 24px;
}
.brand-timeline__head .eyebrow { color: var(--aqua-bloom); }
.brand-timeline__head h2 {
  font-size: clamp(26px, 3.6vw, 36px);
  font-weight: 700;
  margin-top: 8px;
  color: var(--deep-petal);
}
.brand-timeline__list {
  max-width: 1000px;
  margin: 48px auto 0;
  padding: 0 24px;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.brand-timeline__row {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 24px;
  position: relative;
  padding: 16px 0 40px;
}
.brand-timeline__col-icon {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.brand-timeline__row:not(:last-child) .brand-timeline__col-icon::after {
  content: "";
  position: absolute;
  top: 72px;
  bottom: -40px;
  width: 2px;
  background: var(--sunshine-butter);
  border-radius: 2px;
}
.brand-timeline__badge {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--sunshine-butter);
  display: grid;
  place-items: center;
  position: relative;
  z-index: 2;
  transition: transform 300ms ease;
}
.brand-timeline__row:hover .brand-timeline__badge { transform: scale(1.08) rotate(-6deg); }
.brand-timeline__year {
  font-family: var(--font-accent);
  font-size: 22px;
  color: var(--aqua-bloom);
}
.brand-timeline__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 18px;
  color: var(--deep-petal);
  margin-top: 4px;
}
.brand-timeline__desc {
  margin-top: 8px;
  font-size: 15.5px;
  line-height: 1.65;
  color: rgba(45, 58, 53, 0.75);
}
@media (max-width: 720px) {
  .brand-timeline__row { grid-template-columns: 64px 1fr; gap: 16px; }
  .brand-timeline__row:not(:last-child) .brand-timeline__col-icon::after { top: 64px; }
}

/* ============================================================
   PRODUCTS — Page header (products-section-1)
   ============================================================ */
.prod-header {
  background: var(--soft-cloud);
  padding: 80px 0 64px;
  position: relative;
}
.prod-header__inner {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 7fr 5fr;
  align-items: end;
  gap: 32px;
}
.prod-header__text { max-width: 720px; }
.prod-header__eyebrow { color: var(--lumi-coral); }
.prod-header__headline {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(32px, 5.2vw, 56px);
  line-height: 1.1;
  margin-top: 12px;
  color: var(--deep-petal);
}
.prod-header__sub {
  margin-top: 20px;
  font-size: 18px;
  line-height: 1.65;
  color: rgba(45, 58, 53, 0.7);
  max-width: 560px;
}
.prod-header__decor {
  height: 220px;
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
}
.prod-header__rule {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 1.5px;
  background: var(--aqua-bloom);
  opacity: 0.7;
  transform: scaleX(0);
  transform-origin: left center;
  animation: lb-rule-grow 1100ms 400ms cubic-bezier(.2,.7,.2,1) forwards;
}
@keyframes lb-rule-grow { to { transform: scaleX(1); } }
@media (max-width: 880px) {
  .prod-header__inner { grid-template-columns: 1fr; }
  .prod-header__decor { display: none; }
}

/* ============================================================
   PRODUCTS — Gallery (products-section-2)
   ============================================================ */
.prod-gallery {
  background: var(--bloom-milk);
  padding: 72px 0 80px;
  position: relative;
  overflow: hidden;
}
.prod-gallery__giant {
  position: absolute;
  top: 16px;
  left: -50px;
  font-family: var(--font-accent);
  font-size: clamp(56px, 12vw, 112px);
  line-height: 1;
  color: var(--lumi-coral);
  opacity: 0.32;
  text-transform: uppercase;
  pointer-events: none;
  white-space: nowrap;
  z-index: 0;
}
.prod-gallery__eyebrow {
  position: relative;
  z-index: 1;
  color: var(--aqua-bloom);
  text-align: left;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: block;
}
.prod-gallery__grid {
  max-width: var(--container);
  margin: 80px auto 0;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  position: relative;
  z-index: 1;
}
.prod-gallery__card {
  background: var(--bloom-milk);
  border-radius: 24px;
  border: 1.5px solid var(--glow-peach);
  box-shadow: 0 4px 16px rgba(45, 58, 53, 0.08);
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  transition: transform 360ms cubic-bezier(.2,.7,.2,1), box-shadow 360ms ease, border-color 360ms ease;
}
.prod-gallery__card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 6px;
  background: var(--glow-peach);
  z-index: 2;
}
.prod-gallery__card:hover {
  transform: translateY(-6px);
  border-color: var(--lumi-coral);
  box-shadow: 0 16px 28px rgba(255, 111, 94, 0.18);
}
.prod-gallery__img {
  background: linear-gradient(135deg, rgba(255, 203, 164, 0.55), rgba(255, 248, 244, 0.5));
  aspect-ratio: 4 / 3;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px;
  position: relative;
}
.prod-gallery__img svg {
  transition: transform 600ms cubic-bezier(.2,.7,.2,1);
}
.prod-gallery__card:hover .prod-gallery__img svg { transform: scale(1.05); }
.prod-gallery__body { padding: 16px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.prod-gallery__pills { display: flex; flex-wrap: wrap; gap: 6px; }
.prod-gallery__pill {
  font-family: var(--font-accent);
  font-size: 10.5px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  background: var(--sunshine-butter);
  color: var(--deep-petal);
  padding: 4px 10px;
  border-radius: 6px;
  line-height: 1.2;
}
.prod-gallery__pill--aqua { background: var(--aqua-bloom); color: var(--deep-petal); }
.prod-gallery__pill--coral { background: var(--lumi-coral); color: #fff; }
.prod-gallery__title { font-family: var(--font-heading); font-weight: 700; font-size: 18px; color: var(--deep-petal); }
.prod-gallery__desc {
  font-size: 14.5px;
  line-height: 1.55;
  color: rgba(45, 58, 53, 0.75);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.prod-gallery__meta {
  font-size: 13px;
  color: rgba(45, 58, 53, 0.55);
}
.prod-gallery__btn {
  margin-top: auto;
  background: var(--lumi-coral);
  color: var(--bloom-milk);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 15px;
  border: none;
  border-radius: 12px;
  padding: 12px 16px;
  cursor: pointer;
  transition: background 220ms ease, transform 220ms ease;
}
.prod-gallery__btn:hover { background: #ff5a47; transform: translateY(-2px); }

@media (max-width: 1024px) {
  .prod-gallery__grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .prod-gallery__grid { grid-template-columns: 1fr; }
  .prod-gallery__giant { font-size: 56px; left: -10px; }
}

/* ============================================================
   PRODUCTS — Comparison (products-section-3)
   ============================================================ */
.prod-compare {
  background: var(--petal-mint);
  padding: 80px 0;
}
.prod-compare__head { max-width: var(--container); margin: 0 auto; padding: 0 24px; }
.prod-compare__eyebrow { color: rgba(45, 58, 53, 0.65); }
.prod-compare__h2 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(28px, 3.8vw, 40px);
  margin-top: 12px;
  max-width: 600px;
  color: var(--deep-petal);
}
.prod-compare__sub {
  margin-top: 12px;
  font-size: 17px;
  color: rgba(45, 58, 53, 0.7);
}
.prod-compare__grid {
  max-width: var(--container);
  margin: 40px auto 0;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.prod-compare__card {
  background: var(--bloom-milk);
  border-radius: 20px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 320ms ease, box-shadow 320ms ease;
}
.prod-compare__card:hover {
  transform: translateY(-6px);
  box-shadow: 0 12px 24px rgba(45, 58, 53, 0.12);
}
.prod-compare__bar { height: 8px; width: 100%; }
.prod-compare__bar--lotion { background: var(--aqua-bloom); }
.prod-compare__bar--butter { background: var(--glow-peach); }
.prod-compare__bar--oil    { background: var(--sunshine-butter); }
.prod-compare__bar--scrub  { background: var(--lumi-coral); }

.prod-compare__body { padding: 20px; display: flex; flex-direction: column; gap: 10px; }
.prod-compare__name { font-family: var(--font-heading); font-weight: 700; font-size: 20px; color: var(--deep-petal); }
.prod-compare__row { display: flex; flex-direction: column; gap: 2px; }
.prod-compare__row .label {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--aqua-bloom);
}
.prod-compare__row .val {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 14px;
  color: var(--deep-petal);
}
.prod-compare__desc {
  font-size: 14px;
  line-height: 1.6;
  color: rgba(45, 58, 53, 0.75);
}
.prod-compare__note {
  max-width: var(--container);
  margin: 24px auto 0;
  padding: 16px 24px;
  background: rgba(91, 200, 208, 0.15);
  border-radius: 12px;
  font-size: 13px;
  color: rgba(45, 58, 53, 0.7);
  text-align: center;
}
@media (max-width: 980px) { .prod-compare__grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 560px) { .prod-compare__grid { grid-template-columns: 1fr; } }

/* ============================================================
   PRODUCTS — Standards feature grid (products-section-4)
   ============================================================ */
.prod-stds {
  background: var(--sunshine-butter);
  padding: 80px 0;
}
.prod-stds__head { max-width: var(--container); margin: 0 auto; padding: 0 24px; }
.prod-stds__eyebrow { color: rgba(45, 58, 53, 0.65); }
.prod-stds__h2 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(28px, 3.8vw, 40px);
  margin-top: 12px;
  max-width: 520px;
  color: var(--deep-petal);
}
.prod-stds__sub {
  margin-top: 12px;
  font-size: 17px;
  color: rgba(45, 58, 53, 0.7);
  max-width: 480px;
}
.prod-stds__grid {
  max-width: var(--container);
  margin: 48px auto 0;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.prod-stds__item {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.prod-stds__badge {
  width: 80px;
  height: 80px;
  background: var(--bloom-milk);
  border-radius: 50%;
  display: grid;
  place-items: center;
  box-shadow: 0 4px 12px rgba(45, 58, 53, 0.1);
  transition: transform 320ms ease, box-shadow 320ms ease;
}
.prod-stds__item:hover .prod-stds__badge {
  transform: rotate(-6deg) translateY(-4px);
  box-shadow: 0 12px 22px rgba(45, 58, 53, 0.14);
}
.prod-stds__name { font-family: var(--font-heading); font-weight: 700; font-size: 20px; margin-top: 16px; color: var(--deep-petal); }
.prod-stds__desc {
  font-size: 14.5px;
  color: rgba(45, 58, 53, 0.72);
  line-height: 1.6;
  margin-top: 8px;
  max-width: 220px;
}
.prod-stds__cta {
  max-width: var(--container);
  margin: 48px auto 0;
  padding: 0 24px;
}
@media (max-width: 720px) { .prod-stds__grid { grid-template-columns: repeat(2, 1fr); } }

/* ============================================================
   PRODUCTS — Dark CTA Close (products-section-5)
   ============================================================ */
.prod-close {
  background: var(--deep-petal);
  color: var(--bloom-milk);
  padding: 96px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.prod-close .container { position: relative; z-index: 1; }
.prod-close__eyebrow { color: var(--petal-mint); }
.prod-close__h2 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(28px, 4.4vw, 48px);
  color: var(--bloom-milk);
  margin-top: 12px;
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.15;
}
.prod-close__sub {
  margin: 16px auto 0;
  font-size: 17px;
  color: rgba(255, 248, 244, 0.78);
  max-width: 520px;
  line-height: 1.65;
}
.prod-close__btns {
  margin-top: 36px;
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}
.btn-mint-outline {
  background: transparent;
  border: 2px solid var(--petal-mint);
  color: var(--petal-mint);
}
.btn-mint-outline:hover {
  background: var(--petal-mint);
  color: var(--deep-petal);
}

/* ============================================================
   SUSTAINABILITY — Page header (sustainability-section-1)
   ============================================================ */
.sus-header {
  background: var(--petal-mint);
  padding: 88px 0 80px;
  text-align: center;
  min-height: 520px;
  display: flex;
  align-items: center;
}
.sus-header__inner { width: 100%; }
.sus-header__art {
  margin: 0 auto 16px;
  width: 200px;
  animation: lb-drift 9s ease-in-out infinite;
}
.sus-header__eyebrow { color: var(--deep-petal); }
.sus-header__h1 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(32px, 5.6vw, 64px);
  line-height: 1.1;
  margin: 12px auto 0;
  max-width: 760px;
  color: var(--deep-petal);
}
.sus-header__h1 .accent { color: var(--lumi-coral); }
.sus-header__sub {
  margin: 20px auto 0;
  font-size: 18px;
  color: rgba(45, 58, 53, 0.8);
  max-width: 560px;
  line-height: 1.65;
}

/* ============================================================
   SUSTAINABILITY — Stats (sustainability-section-2)
   ============================================================ */
.sus-stats {
  background: var(--bloom-milk);
  padding: 72px 0;
}
.sus-stats__grid {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 55fr 45fr;
  gap: 48px;
  align-items: start;
}
.sus-stats__cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
.sus-stats__card {
  background: var(--bloom-milk);
  border: 1.5px solid var(--glow-peach);
  border-radius: 20px;
  padding: 24px;
  transition: transform 320ms ease, border-color 320ms ease;
}
.sus-stats__card:hover {
  transform: translateY(-4px);
  border-color: var(--lumi-coral);
}
.sus-stats__num {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(32px, 4.4vw, 56px);
  line-height: 1;
}
.sus-stats__card:nth-child(odd) .sus-stats__num { color: var(--lumi-coral); }
.sus-stats__card:nth-child(even) .sus-stats__num { color: var(--aqua-bloom); }
.sus-stats__desc {
  margin-top: 12px;
  font-size: 14.5px;
  color: var(--deep-petal);
  line-height: 1.6;
}
.sus-stats__chart-eye { color: var(--aqua-bloom); display: block; }
.sus-stats__chart-h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(24px, 3vw, 36px);
  margin-top: 8px;
  color: var(--deep-petal);
}
.sus-stats__chart { margin-top: 24px; display: flex; flex-direction: column; gap: 16px; }
.sus-stats__bar-row { display: flex; flex-direction: column; gap: 6px; }
.sus-stats__bar-row .label {
  font-size: 14px;
  color: var(--deep-petal);
}
.sus-stats__bar-track {
  height: 14px;
  width: 100%;
  background: var(--soft-cloud);
  border-radius: 10px;
  overflow: hidden;
  position: relative;
}
.sus-stats__bar-fill {
  height: 100%;
  border-radius: 10px;
  width: 0%;
  transition: width 1400ms cubic-bezier(.2,.7,.2,1);
}
.sus-stats__bar-track.is-visible .sus-stats__bar-fill { width: var(--w, 78%); }
.sus-stats__bar-fill--coral { background: var(--lumi-coral); }
.sus-stats__bar-fill--aqua  { background: var(--aqua-bloom); }
.sus-stats__bar-fill--butter {
  background: repeating-linear-gradient(
    45deg,
    var(--sunshine-butter) 0px,
    var(--sunshine-butter) 10px,
    #ffd700 10px,
    #ffd700 20px
  );
}
@media (max-width: 880px) {
  .sus-stats__grid { grid-template-columns: 1fr; }
  .sus-stats__cards { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 520px) {
  .sus-stats__cards { grid-template-columns: 1fr; }
}

/* ============================================================
   SUSTAINABILITY — Feature grid (sustainability-section-3)
   ============================================================ */
.sus-pillars {
  background: var(--soft-cloud);
  padding: 72px 0;
}
.sus-pillars__head { max-width: var(--container); margin: 0 auto; padding: 0 24px; }
.sus-pillars__eyebrow { color: var(--aqua-bloom); }
.sus-pillars__h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(26px, 3.6vw, 38px);
  margin-top: 8px;
  color: var(--deep-petal);
}
.sus-pillars__sub {
  margin-top: 12px;
  font-size: 17px;
  color: rgba(45, 58, 53, 0.75);
  max-width: 520px;
}
.sus-pillars__grid {
  max-width: var(--container);
  margin: 40px auto 0;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.sus-pillars__card {
  background: var(--bloom-milk);
  border-radius: 24px;
  padding: 28px;
  box-shadow: 0 4px 16px rgba(45, 58, 53, 0.08);
  transition: transform 320ms ease, box-shadow 320ms ease;
}
.sus-pillars__card:hover {
  transform: translateY(-6px);
  box-shadow: 0 14px 28px rgba(45, 58, 53, 0.12);
}
.sus-pillars__icon-wrap {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  margin-bottom: 18px;
}
.sus-pillars__card:nth-child(1) .sus-pillars__icon-wrap { background: var(--sunshine-butter); }
.sus-pillars__card:nth-child(2) .sus-pillars__icon-wrap { background: var(--petal-mint); }
.sus-pillars__card:nth-child(3) .sus-pillars__icon-wrap { background: var(--glow-peach); }
.sus-pillars__card:nth-child(4) .sus-pillars__icon-wrap { background: var(--aqua-bloom); }
.sus-pillars__card h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 20px;
  color: var(--deep-petal);
}
.sus-pillars__card p {
  margin-top: 8px;
  font-size: 15px;
  line-height: 1.65;
  color: rgba(45, 58, 53, 0.8);
}
@media (max-width: 1024px) { .sus-pillars__grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 560px) { .sus-pillars__grid { grid-template-columns: 1fr; } }

/* ============================================================
   SUSTAINABILITY — Timeline (sustainability-section-4) — signature
   ============================================================ */
.sus-roadmap {
  background: var(--deep-petal);
  color: var(--bloom-milk);
  padding: 80px 0;
  position: relative;
}
.sus-roadmap__head { text-align: center; max-width: 720px; margin: 0 auto; padding: 0 24px; }
.sus-roadmap__head .eyebrow { color: var(--petal-mint); }
.sus-roadmap__h2 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(28px, 4vw, 44px);
  margin-top: 10px;
  color: var(--bloom-milk);
}
.sus-roadmap__sub {
  margin: 16px auto 0;
  font-size: 17px;
  color: rgba(255, 248, 244, 0.7);
  max-width: 500px;
  line-height: 1.65;
}
.sus-roadmap__list {
  position: relative;
  max-width: 960px;
  margin: 48px auto 0;
  padding: 0 24px;
}
.sus-roadmap__spine {
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--aqua-bloom);
  opacity: 0.7;
  transform: translateX(-50%);
}
.sus-roadmap__row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 48px;
  position: relative;
  padding: 24px 0;
  min-height: 140px;
}
.sus-roadmap__row::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--aqua-bloom);
  transform: translate(-50%, -50%);
  box-shadow: 0 0 0 4px var(--deep-petal);
}
.sus-roadmap__entry {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  text-align: right;
}
.sus-roadmap__row:nth-child(even) .sus-roadmap__entry,
.sus-roadmap__row:nth-child(even) .sus-roadmap__spacer {
  grid-column: 2;
  align-items: flex-start;
  text-align: left;
}
.sus-roadmap__row:nth-child(even) .sus-roadmap__spacer { grid-column: 1; }
.sus-roadmap__row:nth-child(even) .sus-roadmap__entry { grid-column: 2; }
.sus-roadmap__row:nth-child(odd)  .sus-roadmap__entry { grid-column: 1; }
.sus-roadmap__row:nth-child(odd)  .sus-roadmap__spacer { grid-column: 2; }
.sus-roadmap__year {
  font-family: var(--font-accent);
  font-size: clamp(40px, 5.4vw, 72px);
  color: var(--sunshine-butter);
  line-height: 1;
}
.sus-roadmap__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 20px;
  color: var(--bloom-milk);
  margin-top: 8px;
}
.sus-roadmap__desc {
  margin-top: 8px;
  font-size: 15px;
  color: rgba(255, 248, 244, 0.78);
  line-height: 1.65;
  max-width: 340px;
}
.sus-roadmap__badge {
  margin-top: 14px;
  display: inline-block;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--deep-petal);
  padding: 6px 14px;
  border-radius: 9999px;
}
.sus-roadmap__badge[data-status="Complete"]    { background: var(--petal-mint); }
.sus-roadmap__badge[data-status="In Progress"] { background: var(--aqua-bloom); }
.sus-roadmap__badge[data-status="Planned"]     { background: var(--glow-peach); }

@media (max-width: 720px) {
  .sus-roadmap__list { padding-left: 56px; padding-right: 24px; }
  .sus-roadmap__spine { left: 32px; transform: none; }
  .sus-roadmap__row { grid-template-columns: 1fr; gap: 0; }
  .sus-roadmap__row::before { left: 32px; }
  .sus-roadmap__row:nth-child(even) .sus-roadmap__entry,
  .sus-roadmap__row:nth-child(odd) .sus-roadmap__entry {
    grid-column: 1; align-items: flex-start; text-align: left;
  }
  .sus-roadmap__spacer { display: none; }
  .sus-roadmap__year { font-size: 48px; }
}

/* ============================================================
   CONTACT — Page header (contact-section-1)
   ============================================================ */
.contact-header {
  background: var(--bloom-milk);
  padding: 96px 0 80px;
  position: relative;
  overflow: hidden;
}
.contact-header::after {
  content: "";
  position: absolute;
  top: -40%;
  right: -20%;
  width: 70%;
  height: 140%;
  background: radial-gradient(circle, rgba(255, 203, 164, 0.55), rgba(255, 203, 164, 0) 60%);
  pointer-events: none;
}
.contact-header__inner {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 7fr 5fr;
  align-items: center;
  gap: 32px;
  position: relative;
  z-index: 1;
}
.contact-header__eyebrow { color: var(--lumi-coral); }
.contact-header__h1 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(36px, 6vw, 68px);
  line-height: 1.05;
  margin-top: 16px;
  color: var(--deep-petal);
}
.contact-header__h1 .accent { color: var(--lumi-coral); }
.contact-header__sub {
  margin-top: 24px;
  font-size: 18px;
  color: rgba(45, 58, 53, 0.7);
  line-height: 1.65;
  max-width: 520px;
}
.contact-header__art {
  position: relative;
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  margin-right: -40px;
}
.contact-header__art svg { animation: lb-drift 6s ease-in-out infinite; }
@media (max-width: 880px) {
  .contact-header__inner { grid-template-columns: 1fr; }
  .contact-header__art { justify-content: center; margin: 24px 0 0; height: 240px; }
}

/* ============================================================
   CONTACT — Block (contact-section-2)
   ============================================================ */
.contact-block {
  background: var(--soft-cloud);
  padding: 80px 0;
}
.contact-block__grid {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 40px;
  align-items: start;
}
.contact-block__head .eyebrow { color: var(--aqua-bloom); }
.contact-block__h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(26px, 3.6vw, 38px);
  margin-top: 8px;
  color: var(--deep-petal);
}
.contact-block__sub {
  margin-top: 12px;
  font-size: 16px;
  color: rgba(45, 58, 53, 0.65);
  max-width: 420px;
}
.contact-form-card {
  background: var(--bloom-milk);
  border-radius: 24px;
  padding: 32px;
  margin-top: 24px;
}
.contact-form-row { display: flex; flex-direction: column; gap: 6px; margin-bottom: 18px; }
.contact-form-row label {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 14px;
  color: var(--deep-petal);
}
.contact-form-row input,
.contact-form-row textarea,
.contact-form-row select {
  font-family: var(--font-body);
  font-size: 15px;
  padding: 12px 14px;
  background: var(--bloom-milk);
  border: 2px solid var(--petal-mint);
  border-radius: 12px;
  color: var(--deep-petal);
  transition: border-color 220ms ease, box-shadow 220ms ease;
  outline: none;
}
.contact-form-row input:focus,
.contact-form-row textarea:focus,
.contact-form-row select:focus {
  border-color: var(--aqua-bloom);
  box-shadow: 0 0 0 4px rgba(91, 200, 208, 0.18);
}
.contact-form-row textarea { resize: vertical; min-height: 120px; }
.contact-form-submit {
  width: 100%;
  background: var(--lumi-coral);
  color: var(--bloom-milk);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 17px;
  border: none;
  border-radius: 14px;
  padding: 16px;
  cursor: pointer;
  transition: background 240ms ease, transform 240ms ease;
}
.contact-form-submit:hover { background: #ff5a47; transform: translateY(-2px) scale(1.01); }

.contact-block__emails { display: flex; flex-direction: column; gap: 16px; margin-top: 56px; }
.contact-block__email-card {
  background: var(--bloom-milk);
  border-radius: 16px;
  border-left: 4px solid var(--petal-mint);
  padding: 20px;
  transition: border-color 280ms ease, transform 280ms ease;
}
.contact-block__email-card:hover {
  border-left-color: var(--lumi-coral);
  transform: translateX(4px);
}
.contact-block__email-title { font-family: var(--font-heading); font-weight: 600; font-size: 18px; color: var(--deep-petal); }
.contact-block__email-desc { font-size: 14.5px; color: rgba(45, 58, 53, 0.72); margin-top: 4px; line-height: 1.55; }
.contact-block__email-link {
  display: inline-block;
  margin-top: 6px;
  color: var(--aqua-bloom);
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 14.5px;
  border-bottom: 1px solid currentColor;
}
@media (max-width: 880px) {
  .contact-block__grid { grid-template-columns: 1fr; }
  .contact-block__emails { margin-top: 24px; }
}

/* ============================================================
   CONTACT — FAQ (contact-section-3)
   ============================================================ */
.contact-faq {
  background: var(--petal-mint);
  padding: 72px 0;
}
.contact-faq__grid {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 3fr 9fr;
  gap: 40px;
}
.contact-faq__left { position: relative; min-height: 120px; }
.contact-faq__left .eyebrow { color: var(--deep-petal); }
.contact-faq__watermark {
  position: absolute;
  left: 0;
  bottom: -20px;
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 80px;
  color: var(--deep-petal);
  opacity: 0.18;
  transform: rotate(-90deg) translateX(-100%);
  transform-origin: top left;
  white-space: nowrap;
  line-height: 1;
}
.contact-faq__right { }
.contact-faq__h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(26px, 3.6vw, 36px);
  color: var(--deep-petal);
  margin-bottom: 32px;
}
.contact-faq__list { display: flex; flex-direction: column; gap: 10px; }
.contact-faq__item {
  background: var(--bloom-milk);
  border-radius: 16px;
  padding: 20px 24px;
  cursor: pointer;
  transition: box-shadow 240ms ease;
}
.contact-faq__item:hover { box-shadow: 0 6px 16px rgba(45, 58, 53, 0.08); }
.contact-faq__q {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 18px;
  color: var(--deep-petal);
}
.contact-faq__plus {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--lumi-coral);
  color: #fff;
  font-family: var(--font-heading);
  font-weight: 700;
  transition: transform 280ms cubic-bezier(.2,.7,.2,1), background 280ms ease;
  flex-shrink: 0;
}
.contact-faq__item.is-open .contact-faq__plus { background: var(--aqua-bloom); transform: rotate(45deg); }
.contact-faq__a {
  overflow: hidden;
  max-height: 0;
  transition: max-height 380ms cubic-bezier(.2,.7,.2,1), margin-top 200ms ease, padding-top 200ms ease;
  font-size: 16px;
  line-height: 1.65;
  color: rgba(45, 58, 53, 0.75);
  border-top: 0 solid var(--petal-mint);
  margin-top: 0;
  padding-top: 0;
}
.contact-faq__item.is-open .contact-faq__a {
  max-height: 320px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 2px solid var(--petal-mint);
}
@media (max-width: 880px) {
  .contact-faq__grid { grid-template-columns: 1fr; }
  .contact-faq__watermark { display: none; }
  .contact-faq__left { min-height: 0; }
}

/* ============================================================
   CONTACT — Stay Connected (contact-section-4)
   ============================================================ */
.contact-social {
  background: var(--bloom-milk);
  padding: 80px 0;
  text-align: center;
}
.contact-social__eye {
  display: inline-block;
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--sunshine-butter);
  background: var(--deep-petal);
  padding: 6px 14px;
  border-radius: 8px;
}
.contact-social__h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(26px, 3.4vw, 38px);
  margin-top: 16px;
  color: var(--deep-petal);
}
.contact-social__sub {
  margin: 12px auto 0;
  font-size: 17px;
  color: rgba(45, 58, 53, 0.65);
  max-width: 560px;
  line-height: 1.6;
}
.contact-social__grid {
  max-width: 1100px;
  margin: 40px auto 0;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.contact-social__card {
  background: var(--soft-cloud);
  border-radius: 24px;
  padding: 32px;
  text-align: left;
  position: relative;
  border-bottom: 3px solid transparent;
  transition: transform 320ms ease, box-shadow 320ms ease, border-color 320ms ease;
}
.contact-social__card:hover {
  transform: translateY(-6px);
  box-shadow: 0 14px 28px rgba(45, 58, 53, 0.10);
  border-bottom-color: var(--lumi-coral);
}
.contact-social__icon {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--bloom-milk);
  border: 2px solid var(--petal-mint);
  display: grid;
  place-items: center;
  transition: transform 320ms ease;
}
.contact-social__card:hover .contact-social__icon { transform: rotate(-6deg) scale(1.05); }
.contact-social__name { font-family: var(--font-heading); font-weight: 600; font-size: 22px; margin-top: 16px; color: var(--deep-petal); }
.contact-social__desc { font-size: 15px; color: rgba(45, 58, 53, 0.7); margin-top: 8px; line-height: 1.55; }
.contact-social__tag {
  display: inline-block;
  margin-top: 12px;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 9999px;
  color: var(--deep-petal);
  background: var(--aqua-bloom);
}
.contact-social__card:nth-child(3) .contact-social__tag { background: var(--sunshine-butter); }
.contact-social__card:nth-child(4) .contact-social__tag { background: var(--petal-mint); }
@media (max-width: 720px) {
  .contact-social__grid { grid-template-columns: 1fr; }
}

/* ============================================================
   CONTACT — CTA Close (contact-section-5)
   ============================================================ */
.contact-cta {
  background: var(--lumi-coral);
  color: #fff;
  padding: 88px 0;
  text-align: center;
  position: relative;
}
.contact-cta .container { position: relative; z-index: 1; max-width: 720px; }
.contact-cta__eye { color: rgba(255, 255, 255, 0.85); }
.contact-cta__h2 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(32px, 4.8vw, 56px);
  margin: 12px auto 0;
  position: relative;
  display: inline-block;
}
.contact-cta__sub {
  margin: 18px auto 0;
  font-size: 18px;
  color: rgba(255, 255, 255, 0.85);
  max-width: 480px;
  line-height: 1.6;
}
.contact-cta__sticker {
  position: absolute;
  top: -32px;
  right: -36px;
  width: 84px;
  height: 84px;
  background: var(--sunshine-butter);
  color: var(--deep-petal);
  display: grid;
  place-items: center;
  text-align: center;
  border-radius: 50%;
  transform: rotate(12deg);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  line-height: 1.2;
  box-shadow: 0 6px 16px rgba(45, 58, 53, 0.15);
  animation: lb-drift 4.5s ease-in-out infinite;
}
.contact-cta__btns {
  margin-top: 32px;
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}
@media (max-width: 720px) {
  .contact-cta__sticker { right: -8px; top: -48px; width: 64px; height: 64px; font-size: 8px; }
}

/* ============================================================
   Generic section base
   ============================================================ */
section { position: relative; }

.sec-pad-lg { padding: 100px 0; }
.sec-pad-md { padding: 80px 0; }
.sec-pad-sm { padding: 56px 0; }

@media (max-width: 720px) {
  .sec-pad-lg { padding: 64px 0; }
  .sec-pad-md { padding: 56px 0; }
  .sec-pad-sm { padding: 40px 0; }
}

/* ============================================================
   HOME — Hero (home-section-1)
   ============================================================ */
.home-hero {
  background: var(--glow-peach);
  padding: 100px 0 56px;
  overflow: visible;
  position: relative;
  z-index: 2;
}

.home-hero__inner {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  min-height: 480px;
  gap: 32px;
  position: relative;
}

.home-hero__text {
  position: relative;
  z-index: 3;
  max-width: 560px;
}

.home-hero__eyebrow { color: var(--lumi-coral); }

.home-hero__headline {
  font-size: clamp(40px, 6vw, 68px);
  font-weight: 800;
  line-height: 1.05;
  margin: 16px 0 0;
  color: var(--deep-petal);
}

.home-hero__headline .accent {
  color: var(--lumi-coral);
  position: relative;
  display: inline-block;
}

.home-hero__sub {
  margin-top: 20px;
  font-size: 18px;
  line-height: 1.65;
  color: rgba(45, 58, 53, 0.8);
  max-width: 480px;
}

.home-hero__ctas {
  margin-top: 32px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.home-hero__btn-primary { animation: lb-pulse-coral 3.6s ease-in-out infinite; }

.home-hero__bloom {
  position: absolute;
  bottom: -120px;
  left: 52%;
  width: 520px;
  height: 520px;
  pointer-events: none;
  z-index: 1;
}

.home-hero__bloom .bloom-petal-ring {
  animation: lb-bloom-rotate 60s linear infinite;
  transform-origin: 240px 240px;
}
.home-hero__bloom .bloom-leaf-ring {
  animation: lb-bloom-rotate 90s linear infinite reverse;
  transform-origin: 240px 240px;
}

.home-hero__sparkles {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}

.home-hero__spark {
  position: absolute;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--sunshine-butter);
  filter: drop-shadow(0 0 6px rgba(255, 229, 102, 0.6));
  animation: lb-drift 6s ease-in-out infinite;
}
.home-hero__spark:nth-child(1) { top: 12%; left: 8%; animation-delay: 0s; }
.home-hero__spark:nth-child(2) { top: 30%; right: 12%; animation-delay: 1s; background: var(--lumi-coral); }
.home-hero__spark:nth-child(3) { bottom: 22%; left: 14%; animation-delay: 2s; background: var(--aqua-bloom); }
.home-hero__spark:nth-child(4) { top: 50%; right: 24%; animation-delay: 3s; background: #fff; }

@media (max-width: 880px) {
  .home-hero__inner { grid-template-columns: 1fr; min-height: 380px; text-align: center; }
  .home-hero__text { margin: 0 auto; }
  .home-hero__sub { margin-left: auto; margin-right: auto; }
  .home-hero__ctas { justify-content: center; }
  .home-hero__bloom { position: relative; bottom: auto; left: auto; width: 280px; height: 280px; margin: 24px auto -100px; }
}

/* ============================================================
