}
.prod-compare__sub {
  margin-top: 12px;
  font-size: 17px;
  color: rgba(45, 58, 53, 0.7);
}
.prod-compare__grid {
  max-width: var(--container);
  margin: 40px auto 0;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.prod-compare__card {
  background: var(--bloom-milk);
  border-radius: 20px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
