}
@media (max-width: 980px) { .prod-compare__grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 560px) { .prod-compare__grid { grid-template-columns: 1fr; } }

/* ============================================================
   PRODUCTS — Standards feature grid (products-section-4)
   ============================================================ */
.prod-stds {
  background: var(--sunshine-butter);
  padding: 80px 0;
}
.prod-stds__head { max-width: var(--container); margin: 0 auto; padding: 0 24px; }
.prod-stds__eyebrow { color: rgba(45, 58, 53, 0.65); }
.prod-stds__h2 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(28px, 3.8vw, 40px);
  margin-top: 12px;
  max-width: 520px;
  color: var(--deep-petal);
}
.prod-stds__sub {
  margin-top: 12px;
  font-size: 17px;
  color: rgba(45, 58, 53, 0.7);
