  border-radius: 12px;
  color: var(--deep-petal);
  transition: border-color 220ms ease, box-shadow 220ms ease;
  outline: none;
}
.contact-form-row input:focus,
.contact-form-row textarea:focus,
.contact-form-row select:focus {
  border-color: var(--aqua-bloom);
  box-shadow: 0 0 0 4px rgba(91, 200, 208, 0.18);
}
.contact-form-row textarea { resize: vertical; min-height: 120px; }
.contact-form-submit {
  width: 100%;
  background: var(--lumi-coral);
  color: var(--bloom-milk);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 17px;
  border: none;
  border-radius: 14px;
  padding: 16px;
  cursor: pointer;
  transition: background 240ms ease, transform 240ms ease;
}
.contact-form-submit:hover { background: #ff5a47; transform: translateY(-2px) scale(1.01); }

.contact-block__emails { display: flex; flex-direction: column; gap: 16px; margin-top: 56px; }
.contact-block__email-card {
  background: var(--bloom-milk);
  border-radius: 16px;
  border-left: 4px solid var(--petal-mint);
  padding: 20px;
  transition: border-color 280ms ease, transform 280ms ease;
}
.contact-block__email-card:hover {
  border-left-color: var(--lumi-coral);
  transform: translateX(4px);
}
.contact-block__email-title { font-family: var(--font-heading); font-weight: 600; font-size: 18px; color: var(--deep-petal); }
.contact-block__email-desc { font-size: 14.5px; color: rgba(45, 58, 53, 0.72); margin-top: 4px; line-height: 1.55; }
.contact-block__email-link {
  display: inline-block;
  margin-top: 6px;
  color: var(--aqua-bloom);
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 14.5px;
  border-bottom: 1px solid currentColor;
}
@media (max-width: 880px) {
  .contact-block__grid { grid-template-columns: 1fr; }
  .contact-block__emails { margin-top: 24px; }
}

/* ============================================================
   CONTACT — FAQ (contact-section-3)
   ============================================================ */
.contact-faq {
  background: var(--petal-mint);
  padding: 72px 0;
}
.contact-faq__grid {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 3fr 9fr;
  gap: 40px;
}
.contact-faq__left { position: relative; min-height: 120px; }
.contact-faq__left .eyebrow { color: var(--deep-petal); }
.contact-faq__watermark {
  position: absolute;
  left: 0;
  bottom: -20px;
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 80px;
  color: var(--deep-petal);
  opacity: 0.18;
  transform: rotate(-90deg) translateX(-100%);
  transform-origin: top left;
  white-space: nowrap;
  line-height: 1;
}
.contact-faq__right { }
.contact-faq__h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(26px, 3.6vw, 36px);
  color: var(--deep-petal);
  margin-bottom: 32px;
}
.contact-faq__list { display: flex; flex-direction: column; gap: 10px; }
.contact-faq__item {
  background: var(--bloom-milk);
  border-radius: 16px;
  padding: 20px 24px;
  cursor: pointer;
  transition: box-shadow 240ms ease;
}
.contact-faq__item:hover { box-shadow: 0 6px 16px rgba(45, 58, 53, 0.08); }
.contact-faq__q {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 18px;
  color: var(--deep-petal);
}
.contact-faq__plus {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--lumi-coral);
  color: #fff;
  font-family: var(--font-heading);
  font-weight: 700;
  transition: transform 280ms cubic-bezier(.2,.7,.2,1), background 280ms ease;
  flex-shrink: 0;
}
.contact-faq__item.is-open .contact-faq__plus { background: var(--aqua-bloom); transform: rotate(45deg); }
.contact-faq__a {
  overflow: hidden;
  max-height: 0;
  transition: max-height 380ms cubic-bezier(.2,.7,.2,1), margin-top 200ms ease, padding-top 200ms ease;
  font-size: 16px;
  line-height: 1.65;
  color: rgba(45, 58, 53, 0.75);
  border-top: 0 solid var(--petal-mint);
  margin-top: 0;
  padding-top: 0;
}
.contact-faq__item.is-open .contact-faq__a {
  max-height: 320px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 2px solid var(--petal-mint);
}
@media (max-width: 880px) {
  .contact-faq__grid { grid-template-columns: 1fr; }
  .contact-faq__watermark { display: none; }
  .contact-faq__left { min-height: 0; }
}

/* ============================================================
   CONTACT — Stay Connected (contact-section-4)
   ============================================================ */
.contact-social {
  background: var(--bloom-milk);
  padding: 80px 0;
  text-align: center;
}
.contact-social__eye {
  display: inline-block;
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--sunshine-butter);
  background: var(--deep-petal);
  padding: 6px 14px;
  border-radius: 8px;
}
.contact-social__h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(26px, 3.4vw, 38px);
  margin-top: 16px;
  color: var(--deep-petal);
}
.contact-social__sub {
  margin: 12px auto 0;
  font-size: 17px;
  color: rgba(45, 58, 53, 0.65);
  max-width: 560px;
  line-height: 1.6;
}
.contact-social__grid {
  max-width: 1100px;
  margin: 40px auto 0;
  padding: 0 24px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.contact-social__card {
  background: var(--soft-cloud);
  border-radius: 24px;
  padding: 32px;
  text-align: left;
  position: relative;
  border-bottom: 3px solid transparent;
  transition: transform 320ms ease, box-shadow 320ms ease, border-color 320ms ease;
}
.contact-social__card:hover {
  transform: translateY(-6px);
  box-shadow: 0 14px 28px rgba(45, 58, 53, 0.10);
  border-bottom-color: var(--lumi-coral);
}
.contact-social__icon {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--bloom-milk);
  border: 2px solid var(--petal-mint);
  display: grid;
  place-items: center;
  transition: transform 320ms ease;
}
.contact-social__card:hover .contact-social__icon { transform: rotate(-6deg) scale(1.05); }
.contact-social__name { font-family: var(--font-heading); font-weight: 600; font-size: 22px; margin-top: 16px; color: var(--deep-petal); }
.contact-social__desc { font-size: 15px; color: rgba(45, 58, 53, 0.7); margin-top: 8px; line-height: 1.55; }
.contact-social__tag {
  display: inline-block;
  margin-top: 12px;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 9999px;
  color: var(--deep-petal);
  background: var(--aqua-bloom);
}
.contact-social__card:nth-child(3) .contact-social__tag { background: var(--sunshine-butter); }
.contact-social__card:nth-child(4) .contact-social__tag { background: var(--petal-mint); }
@media (max-width: 720px) {
  .contact-social__grid { grid-template-columns: 1fr; }
}

/* ============================================================
   CONTACT — CTA Close (contact-section-5)
   ============================================================ */
.contact-cta {
  background: var(--lumi-coral);
  color: #fff;
  padding: 88px 0;
  text-align: center;
  position: relative;
}
.contact-cta .container { position: relative; z-index: 1; max-width: 720px; }
.contact-cta__eye { color: rgba(255, 255, 255, 0.85); }
.contact-cta__h2 {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(32px, 4.8vw, 56px);
  margin: 12px auto 0;
  position: relative;
  display: inline-block;
}
.contact-cta__sub {
  margin: 18px auto 0;
  font-size: 18px;
  color: rgba(255, 255, 255, 0.85);
  max-width: 480px;
  line-height: 1.6;
}
.contact-cta__sticker {
  position: absolute;
  top: -32px;
  right: -36px;
  width: 84px;
  height: 84px;
  background: var(--sunshine-butter);
  color: var(--deep-petal);
  display: grid;
  place-items: center;
  text-align: center;
  border-radius: 50%;
  transform: rotate(12deg);
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  line-height: 1.2;
  box-shadow: 0 6px 16px rgba(45, 58, 53, 0.15);
  animation: lb-drift 4.5s ease-in-out infinite;
}
.contact-cta__btns {
  margin-top: 32px;
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}
@media (max-width: 720px) {
  .contact-cta__sticker { right: -8px; top: -48px; width: 64px; height: 64px; font-size: 8px; }
}

input.content:
import React from 'react';
import { BloomIllustration } from '../assets/Bloom.jsx';
import { LeafPattern } from '../assets/Illustrations.jsx';
import { ProductMockup } from '../assets/Illustrations.jsx';

export function HeroSection({ section }) {
  return (
    <section
      id={section.id}
      data-section-type={section.type}
      className="home-hero"
    >
      <div className="home-hero__sparkles" aria-hidden="true">
        <span className="home-hero__spark" />
        <span className="home-hero__spark" />
        <span className="home-hero__spark" />
        <span className="home-hero__spark" />
      </div>

      <div className="home-hero__inner">
        <div className="home-hero__text">
          <span className="eyebrow home-hero__eyebrow entrance-rise" data-d="1">{section.eyebrow}</span>
          <h1 className="home-hero__headline entrance-rise" data-d="2">
            Your Daily <span className="accent">Glow</span> Starts Here
          </h1>
          <p className="home-hero__sub entrance-rise" data-d="3">{section.subheadline}</p>
          <div className="home-hero__ctas entrance-rise" data-d="4">
            <a href="./products.html" className="btn btn-primary home-hero__btn-primary">{section.ctas[0].label}</a>
            <a href="./brand.html" className="btn btn-secondary">{section.ctas[1].label}</a>
          </div>
        </div>

        <div className="home-hero__bloom entrance-pop" aria-hidden="true">
          <BloomIllustration size={520} />
        </div>
      </div>
    </section>
  );
}

const galleryAccents = ['#FFCBA4', '#FFE566', '#FF6F5E', '#A8E6CF'];
const galleryBadgeText = ['Best\nseller', 'Fan\nFave', 'New', 'Sleep\nRitual'];

export function GallerySection({ section }) {
  return (
    <section
      id={section.id}
      data-section-type={section.type}
      className="home-gallery"
    >
      <div className="home-gallery__intro reveal">
        <span className="eyebrow">{section.eyebrow}</span>
        <h2 className="home-gallery__headline">{section.headline}</h2>
        <p className="home-gallery__sub">{section.subheadline}</p>
      </div>

      <div className="home-gallery__grid">
        {section.items.map((item, i) => (
          <article key={i} className="home-gallery__card reveal" data-d={String(i + 1)}>
            <div className="ribbon" aria-hidden="true" />
            <div className="home-gallery__image">
              <ProductMockup accent={galleryAccents[i]} label={item.title} sub={item.metadata?.size || ''} />
              <div className="home-gallery__badge">
                {galleryBadgeText[i].split('\n').map((line, idx) => <span key={idx}>{line}</span>)}
              </div>
            </div>
            <div className="home-gallery__body">
              <div className="home-gallery__title">{item.title}</div>
              <div className="home-gallery__meta">{item.metadata?.tag} · {item.metadata?.size}</div>
              <p className="home-gallery__desc">{item.description}</p>
            </div>
          </article>
        ))}
      </div>

      <div className="home-gallery__cta-row reveal">
        <a href="./products.html" className="btn btn-primary">{section.ctas[0].label}</a>
      </div>
    </section>
  );
}

export function StatsSection({ section }) {
  return (
    <section
      id={section.id}
      data-section-type={section.type}
      className="home-stats"
    >
      <div className="home-stats__intro reveal">
        <span className="eyebrow">{section.eyebrow}</span>
        <h2 className="home-stats__headline">{section.headline}</h2>
      </div>
      <div className="home-stats__row">
        {section.items.map((item, i) => (
          <div key={i} className="home-stats__cell reveal" data-d={String(i + 1)}>
            <div className="home-stats__num">
              {item.title.includes('★') ? (
                <>
                  4.9 <span className="star">★</span> Avg
                </>
              ) : (
                item.title
              )}
            </div>
            <p className="home-stats__desc">{item.description}</p>
          </div>
        ))}
      </div>
    </section>
  );
}

export function TestimonialSection({ section }) {
  return (
    <section
      id={section.id}
      data-section-type={section.type}
      className="home-test"
    >
      <div className="home-test__head reveal">
        <span className="eyebrow home-test__eyebrow">{section.eyebrow}</span>
        <h2 className="home-test__headline">{section.headline}</h2>
      </div>

      <div className="home-test__cards-wrap">
        <span className="home-test__quote-mark" aria-hidden="true">&ldquo;</span>
        <div className="home-test__cards">
          {section.items.map((item, i) => (
            <article key={i} className="home-test__card reveal" data-d={String(i + 1)}>
              <div className="home-test__card-q" aria-hidden="true">&ldquo;</div>
              <p className="home-test__card-quote">{item.description.replace(/^"|"$/g, '')}</p>
              <div className="home-test__card-name">{item.title}</div>
              <span className="home-test__card-tag">{item.metadata?.product}</span>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

export function HomeCtaSection({ section }) {
  return (
    <section
      id={section.id}
      data-section-type={section.type}
      className="cta-coral"
    >
      <LeafPattern color="#2D3A35" opacity={0.12} />
      <div className="container reveal">
        <span className="eyebrow cta-coral__eyebrow">{section.eyebrow}</span>
        <h2 className="cta-coral__headline">
          Ready to Start Your Ritual<span className="accent">?</span>
        </h2>
        <p className="cta-coral__sub">{section.subheadline}</p>
        <div className="cta-coral__btns">
          <a href="./products.html" className="btn btn-light">{section.ctas[0].label}</a>
          <a href="./brand.html" className="btn btn-ghost-light">{section.ctas[1].label}</a>
        </div>
      </div>
    </section>
  );
}

