        <span className="eyebrow">{section.eyebrow}</span>
        <h2 className="home-gallery__headline">{section.headline}</h2>
        <p className="home-gallery__sub">{section.subheadline}</p>
      </div>

      <div className="home-gallery__grid">
        {section.items.map((item, i) => (
          <article key={i} className="home-gallery__card reveal" data-d={String(i + 1)}>
            <div className="ribbon" aria-hidden="true" />
            <div className="home-gallery__image">
              <ProductMockup accent={galleryAccents[i]} label={item.title} sub={item.metadata?.size || ''} />
              <div className="home-gallery__badge">
                {galleryBadgeText[i].split('\n').map((line, idx) => <span key={idx}>{line}</span>)}
              </div>
            </div>
            <div className="home-gallery__body">
              <div className="home-gallery__title">{item.title}</div>
              <div className="home-gallery__meta">{item.metadata?.tag} · {item.metadata?.size}</div>
              <p className="home-gallery__desc">{item.description}</p>
            </div>
          </article>
        ))}
      </div>

      <div className="home-gallery__cta-row reveal">
        <a href="./products.html" className="btn btn-primary">{section.ctas[0].label}</a>
      </div>
    </section>
  );
}

export function StatsSection({ section }) {
