export function BrandStory({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="brand-story">
      <div className="brand-story__grid">
        <div className="brand-story__left">
          <div className="brand-story__pullquote reveal">
            &ldquo;Made with two hands and a&nbsp;whole lot of belief.&rdquo;
          </div>
          <span className="eyebrow brand-story__eyebrow reveal" data-d="1">{section.eyebrow}</span>
          <h2 className="brand-story__h2 reveal" data-d="2">{section.headline}</h2>
        </div>
        <p className="brand-story__body reveal" data-d="3">{section.body}</p>
