      </div>
      <div className="brand-timeline__list">
        {section.items.map((item, i) => {
          const Icon = milestoneIcons[i] || IconStar;
          const [yearPart, ...rest] = item.title.split(' — ');
          const label = rest.join(' — ');
          return (
            <div key={i} className="brand-timeline__row reveal" data-d={String(i + 1)}>
