import React from 'react';
import { ProductMockup, DotPattern } from '../assets/Illustrations.jsx';
import { IconFlask, IconPaintDrop, IconWave, IconStethoscope, IconLeaf } from '../assets/Icons.jsx';

export function ProductsHeader({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="prod-header">
      <div className="prod-header__inner">
        <div className="prod-header__text">
          <span className="eyebrow prod-header__eyebrow entrance-rise" data-d="1">{section.eyebrow}</span>
          <h1 className="prod-header__headline entrance-rise" data-d="2">
            Every Product, One Purpose:<br />Make You Feel <span style={{ color: 'var(--lumi-coral)' }}>Amazing</span>
          </h1>
          <p className="prod-header__sub entrance-rise" data-d="3">{section.subheadline}</p>
        </div>
        <div className="prod-header__decor" aria-hidden="true">
          <svg width="220" height="220" viewBox="0 0 220 220">
            <circle cx="110" cy="110" r="80" fill="#FFCBA4" opacity="0.5" />
            <circle cx="110" cy="110" r="56" fill="#FFE566" />
            <circle cx="110" cy="110" r="28" fill="#FF6F5E" />
          </svg>
        </div>
      </div>
      <div className="container"><div className="prod-header__rule" /></div>
    </section>
  );
}

const accentForCategory = (cat) => {
  switch (cat) {
    case 'Lotion': return '#A8E6CF';
    case 'Scrub': return '#FF6F5E';
    case 'Oil': return '#FFE566';
    case 'Butter': return '#FFCBA4';
    case 'Foot Care': return '#5BC8D0';
    case 'Bath': return '#FFCBA4';
    default: return '#FFCBA4';
  }
};

const tagForIndex = (i) => {
  const tags = ['Bestseller', 'Fan Fave', 'New', 'Original', 'Sensitive', 'Refresh', 'Detox', 'Soak'];
  return tags[i] || 'New';
};

export function ProductsGallery({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="prod-gallery">
      <div className="prod-gallery__giant" aria-hidden="true">FIND YOUR NEW RITUAL</div>
      <div className="container">
        <span className="eyebrow prod-gallery__eyebrow">{section.eyebrow}</span>
      </div>

      <div className="prod-gallery__grid">
        {section.items.map((item, i) => (
          <article key={i} className="prod-gallery__card reveal" data-d={String((i % 4) + 1)}>
            <div className="prod-gallery__img">
              <ProductMockup
                accent={accentForCategory(item.metadata?.category)}
                label={item.title}
                sub={item.metadata?.size || ''}
              />
            </div>
            <div className="prod-gallery__body">
              <div className="prod-gallery__pills">
                <span className="prod-gallery__pill">{item.metadata?.category}</span>
                {i === 0 && <span className="prod-gallery__pill prod-gallery__pill--coral">Bestseller</span>}
                {i === 2 && <span className="prod-gallery__pill prod-gallery__pill--aqua">New</span>}
              </div>
              <div className="prod-gallery__title">{item.title}</div>
              <p className="prod-gallery__desc">{item.description}</p>
              <div className="prod-gallery__meta">
                {item.metadata?.size} · {item.metadata?.skin_type}
              </div>
              <button type="button" className="prod-gallery__btn">Add to Ritual</button>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

const compareBarClass = (name) => {
  if (name.includes('Lotion')) return 'prod-compare__bar--lotion';
  if (name.includes('Butter')) return 'prod-compare__bar--butter';
  if (name.includes('Oil')) return 'prod-compare__bar--oil';
  if (name.includes('Scrub')) return 'prod-compare__bar--scrub';
  return 'prod-compare__bar--lotion';
};

