            <div className={`prod-compare__bar ${compareBarClass(item.title)}`} />
            <div className="prod-compare__body">
              <div className="prod-compare__name">{item.title}</div>
              <div className="prod-compare__row">
                <span className="label">Best for</span>
                <span className="val">{item.metadata?.best_for}</span>
              </div>
              <div className="prod-compare__row">
                <span className="label">When</span>
                <span className="val">{item.metadata?.when}</span>
              </div>
              <p className="prod-compare__desc">{item.description}</p>
            </div>
          </article>
        ))}
      </div>
