import React, { useEffect, useRef } from 'react';
import { GlobeVine } from '../assets/Illustrations.jsx';
import { IconLeaf, IconRecycle, IconGlobe, IconPeople } from '../assets/Icons.jsx';

export function SusHeader({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="sus-header">
      <div className="container sus-header__inner">
        <div className="sus-header__art entrance-pop"><GlobeVine size={200} /></div>
        <span className="eyebrow sus-header__eyebrow entrance-rise" data-d="1">{section.eyebrow}</span>
        <h1 className="sus-header__h1 entrance-rise" data-d="2">
          Good for Your Skin. <span className="accent">Better</span> for the Planet.
        </h1>
        <p className="sus-header__sub entrance-rise" data-d="3">{section.subheadline}</p>
      </div>
    </section>
  );
}

const barWidths = ['78%', '100%', '40%'];
const barClasses = ['sus-stats__bar-fill--coral', 'sus-stats__bar-fill--aqua', 'sus-stats__bar-fill--butter'];
const barLabels = ['Recycled / recyclable packaging', 'Carbon-offset shipping', 'Plastic-free by 2026 (target)'];

function ChartBar({ idx }) {
  const ref = useRef(null);
  useEffect(() => {
    if (!ref.current) return;
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => {
        if (e.isIntersecting) {
          e.target.classList.add('is-visible');
          io.unobserve(e.target);
        }
      });
    }, { threshold: 0.4 });
    io.observe(ref.current);
    return () => io.disconnect();
  }, []);
  return (
    <div className="sus-stats__bar-row">
      <span className="label">{barLabels[idx]} <strong>{barWidths[idx]}</strong></span>
      <div ref={ref} className="sus-stats__bar-track" style={{ '--w': barWidths[idx] }}>
        <div className={`sus-stats__bar-fill ${barClasses[idx]}`} />
      </div>
    </div>
  );
}

export function SusStats({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="sus-stats">
      <div className="sus-stats__grid">
        <div className="sus-stats__cards">
          {section.items.map((item, i) => (
            <article key={i} className="sus-stats__card reveal" data-d={String(i + 1)}>
              <div className="sus-stats__num">{item.title}</div>
              <p className="sus-stats__desc">{item.description}</p>
            </article>
          ))}
        </div>
        <div className="sus-stats__chart-side reveal">
          <span className="eyebrow sus-stats__chart-eye">{section.eyebrow}</span>
          <h2 className="sus-stats__chart-h2">{section.headline}</h2>
          <div className="sus-stats__chart">
            {[0, 1, 2].map((i) => <ChartBar key={i} idx={i} />)}
          </div>
        </div>
      </div>
    </section>
  );
}

const pillarIcons = [IconLeaf, IconRecycle, IconGlobe, IconPeople];

export function SusPillars({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="sus-pillars">
      <div className="sus-pillars__head reveal">
        <span className="eyebrow sus-pillars__eyebrow">{section.eyebrow}</span>
        <h2 className="sus-pillars__h2">{section.headline}</h2>
        <p className="sus-pillars__sub">{section.subheadline}</p>
      </div>
      <div className="sus-pillars__grid">
        {section.items.map((item, i) => {
          const Icon = pillarIcons[i];
          return (
            <article key={i} className="sus-pillars__card reveal" data-d={String(i + 1)}>
              <div className="sus-pillars__icon-wrap"><Icon size={28} /></div>
              <h3>{item.title}</h3>
              <p>{item.description}</p>
            </article>
          );
        })}
      </div>
    </section>
  );
}

export function SusRoadmap({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="sus-roadmap">
      <div className="sus-roadmap__head reveal">
        <span className="eyebrow">{section.eyebrow}</span>
        <h2 className="sus-roadmap__h2">{section.headline}</h2>
        <p className="sus-roadmap__sub">{section.subheadline}</p>
      </div>
      <div className="sus-roadmap__list">
        <div className="sus-roadmap__spine" aria-hidden="true" />
        {section.items.map((item, i) => {
          const [yearPart, ...rest] = item.title.split(' — ');
          const label = rest.join(' — ');
          const status = item.metadata?.status || 'Complete';
          const side = i % 2 === 0 ? 'left' : 'right';
          return (
            <div key={i} className="sus-roadmap__row reveal" data-side={side} data-d={String((i % 4) + 1)}>
              <div className="sus-roadmap__entry">
                <div className="sus-roadmap__year">{yearPart}</div>
                <div className="sus-roadmap__title">{label}</div>
                <p className="sus-roadmap__desc">{item.description}</p>
                <span className="sus-roadmap__badge" data-status={status}>{status}</span>
              </div>
              <div className="sus-roadmap__spacer" aria-hidden="true" />
            </div>
          );
        })}
      </div>
    </section>
  );
}

export function SusCta({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="cta-coral">
      <div className="container reveal">
        <span className="eyebrow cta-coral__eyebrow">{section.eyebrow}</span>
        <h2 className="cta-coral__headline">
          Every Purchase Is a <span className="accent">Vote</span> for Better Beauty
        </h2>
        <p className="cta-coral__sub">{section.subheadline}</p>
        <div className="cta-coral__btns">
          <a href="./products.html" className="btn btn-light">{section.ctas[0].label}</a>
          <a href="./contact.html" className="btn btn-ghost-light">{section.ctas[1].label}</a>
        </div>
      </div>
    </section>
  );
}

