import { Footer } from '../components/Footer.jsx';
import { useReveal } from '../hooks/useReveal.js';
import { usePageBoot } from '../hooks/usePageBoot.js';

import {
  SusHeader,
  SusStats,
  SusPillars,
  SusRoadmap,
  SusCta
} from '../sections/sustainability.jsx';

const page = blueprint.pages.find((p) => p.slug === 'sustainability');

function SustainabilityPage() {
  usePageBoot('sustainability');
  const rootRef = useRef(null);
  useReveal(rootRef);
  const [s1, s2, s3, s4, s5] = page.sections;
  return (
    <div ref={rootRef}>
      <Nav current="sustainability" />
      <main>
        <SusHeader section={s1} />
        <SusStats section={s2} />
        <SusPillars section={s3} />
        <SusRoadmap section={s4} />
        <SusCta section={s5} />
      </main>
      <Footer />
    </div>
  );
}

createRoot(document.getElementById('root')).render(<SustainabilityPage />);

