import React, { useState } from 'react';
import { EnvelopeBloom } from '../assets/Illustrations.jsx';
import { IconCamera, IconPlay, IconEnvelopeStar, IconChat } from '../assets/Icons.jsx';

export function ContactHeader({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="contact-header">
      <div className="contact-header__inner">
        <div className="contact-header__text">
          <span className="eyebrow contact-header__eyebrow entrance-rise" data-d="1">{section.eyebrow}</span>
          <h1 className="contact-header__h1 entrance-rise" data-d="2">
            We're <span className="accent">Real</span> People and We Actually Read These
          </h1>
          <p className="contact-header__sub entrance-rise" data-d="3">{section.subheadline}</p>
        </div>
        <div className="contact-header__art entrance-pop"><EnvelopeBloom size={320} /></div>
      </div>
    </section>
  );
}

function ContactForm() {
  const [submitted, setSubmitted] = useState(false);
  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };
  return (
    <form className="contact-form-card" onSubmit={handleSubmit}>
      <div className="contact-form-row">
        <label htmlFor="cf-name">Name</label>
        <input id="cf-name" type="text" placeholder="What should we call you?" />
      </div>
      <div className="contact-form-row">
        <label htmlFor="cf-email">Email</label>
        <input id="cf-email" type="email" placeholder="hello@yourdomain.com" />
      </div>
      <div className="contact-form-row">
        <label htmlFor="cf-subject">What's this about?</label>
        <select id="cf-subject" defaultValue="Product Question">
          <option>Product Question</option>
          <option>Wholesale</option>
          <option>Press</option>
          <option>Just Saying Hi</option>
          <option>Other</option>
        </select>
      </div>
      <div className="contact-form-row">
        <label htmlFor="cf-message">Message</label>
        <textarea id="cf-message" rows={5} placeholder="Tell us everything." />
      </div>
      <button type="submit" className="contact-form-submit">
        {submitted ? 'Sent — thank you ✿' : 'Send Your Message →'}
      </button>
    </form>
  );
}

export function ContactBlock({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="contact-block">
      <div className="contact-block__grid">
        <div>
          <div className="contact-block__head reveal">
            <span className="eyebrow">{section.eyebrow}</span>
            <h2 className="contact-block__h2">{section.headline}</h2>
            <p className="contact-block__sub">{section.subheadline}</p>
          </div>
          <div className="reveal" data-d="1">
            <ContactForm />
          </div>
        </div>
        <div className="contact-block__emails">
          {section.items.map((item, i) => {
            const email = item.description.split(' ')[0];
            const rest = item.description.replace(/^\S+\s+—\s*/, '');
            return (
              <article key={i} className="contact-block__email-card reveal" data-d={String(i + 1)}>
                <div className="contact-block__email-title">{item.title}</div>
                <p className="contact-block__email-desc">{rest}</p>
                <a className="contact-block__email-link" href={`mailto:${email}`}>{email}</a>
              </article>
            );
          })}
        </div>
      </div>
    </section>
  );
}

function FaqItem({ item, defaultOpen }) {
  const [open, setOpen] = useState(!!defaultOpen);
  return (
    <div className={`contact-faq__item ${open ? 'is-open' : ''}`} onClick={() => setOpen((v) => !v)}>
      <div className="contact-faq__q">
        <span>{item.title}</span>
        <span className="contact-faq__plus" aria-hidden="true">+</span>
      </div>
      <div className="contact-faq__a">{item.description}</div>
    </div>
  );
}

export function ContactFaq({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="contact-faq">
      <div className="contact-faq__grid">
        <div className="contact-faq__left">
          <span className="eyebrow">{section.eyebrow}</span>
          <div className="contact-faq__watermark" aria-hidden="true">FAQ</div>
        </div>
        <div className="contact-faq__right">
          <h2 className="contact-faq__h2 reveal">{section.headline}</h2>
          <div className="contact-faq__list">
            {section.items.map((item, i) => (
              <div key={i} className="reveal" data-d={String(i + 1)}>
                <FaqItem item={item} defaultOpen={i === 0} />
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

const socialIcons = [IconCamera, IconPlay, IconEnvelopeStar, IconChat];

export function ContactSocial({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="contact-social">
      <div className="container reveal">
        <span className="contact-social__eye">{section.eyebrow}</span>
        <h2 className="contact-social__h2">{section.headline}</h2>
        <p className="contact-social__sub">{section.subheadline}</p>
      </div>
      <div className="contact-social__grid">
        {section.items.map((item, i) => {
          const Icon = socialIcons[i];
          const tag = item.metadata?.handle || item.metadata?.frequency || item.metadata?.type;
          return (
            <article key={i} className="contact-social__card reveal" data-d={String(i + 1)}>
              <div className="contact-social__icon"><Icon size={32} /></div>
              <div className="contact-social__name">{item.title}</div>
              <p className="contact-social__desc">{item.description}</p>
              {tag && <span className="contact-social__tag">{tag}</span>}
            </article>
          );
        })}
      </div>
    </section>
  );
}

export function ContactCta({ section }) {
  return (
    <section id={section.id} data-section-type={section.type} className="contact-cta">
      <div className="container reveal">
        <span className="eyebrow contact-cta__eye">{section.eyebrow}</span>
        <h2 className="contact-cta__h2">
          {section.headline}
          <span className="contact-cta__sticker">Your Skin Will Thank You</span>
        </h2>
        <p className="contact-cta__sub">{section.subheadline}</p>
        <div className="contact-cta__btns">
          <a href="./products.html" className="btn btn-light">{section.ctas[0].label}</a>
          <a href="./brand.html" className="btn btn-ghost-light">{section.ctas[1].label}</a>
        </div>
      </div>
    </section>
  );
}

