import React, { useRef } from 'react';
import { createRoot } from 'react-dom/client';
import blueprint from '../data-blueprint.json';
import '../styles/global.css';
import '../styles/sections.css';

import { Nav } from '../components/Nav.jsx';
import { Footer } from '../components/Footer.jsx';
import { useReveal } from '../hooks/useReveal.js';
import { usePageBoot } from '../hooks/usePageBoot.js';

import {
  ContactHeader,
  ContactBlock,
  ContactFaq,
  ContactSocial,
  ContactCta
} from '../sections/contact.jsx';

const page = blueprint.pages.find((p) => p.slug === 'contact');

function ContactPage() {
  usePageBoot('contact');
  const rootRef = useRef(null);
  useReveal(rootRef);
  const [s1, s2, s3, s4, s5] = page.sections;
  return (
    <div ref={rootRef}>
      <Nav current="contact" />
      <main>
        <ContactHeader section={s1} />
        <ContactBlock section={s2} />
        <ContactFaq section={s3} />
        <ContactSocial section={s4} />
        <ContactCta section={s5} />
      </main>
      <Footer />
    </div>
  );
}

createRoot(document.getElementById('root')).render(<ContactPage />);

