import { chromium } from 'playwright';
import fs from 'fs';
const b = await chromium.launch();
const ctx = await b.newContext();
const pg = await ctx.newPage();
const slugs = ['index','brand','products','sustainability','contact'];
const slugToBody = { index:'home', brand:'brand', products:'products', sustainability:'sustainability', contact:'contact' };
const report = {};
for (const s of slugs) {
  try {
    await pg.goto(`http://127.0.0.1:8765/${s}.html`, { waitUntil: 'networkidle', timeout: 15000 });
    const result = await pg.evaluate(() => {
      const sec = [...document.querySelectorAll('section[id]')].map(s => ({
        id: s.id, type: s.dataset.sectionType
      }));
      return {
        bodySlug: document.body.dataset.pageSlug,
        sections: sec,
        h1: document.querySelector('h1')?.innerText || null
      };
    });
