import { useEffect } from 'react';

export function useReveal(rootRef, opts = {}) {
  const { selector = '.reveal', threshold = 0.05, rootMargin = '0px 0px -10% 0px' } = opts;

  useEffect(() => {
    const root = rootRef?.current ?? document;
    const nodes = root.querySelectorAll(selector);
    if (!nodes.length) return;

    // Fail-safe: any element that hasn't been revealed within 3s becomes visible
    const failSafe = setTimeout(() => {
      nodes.forEach((n) => n.classList.add('is-visible'));
    }, 3000);

    if (typeof IntersectionObserver === 'undefined') {
      nodes.forEach((n) => n.classList.add('is-visible'));
      clearTimeout(failSafe);
      return;
    }

    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            io.unobserve(entry.target);
          }
        });
      },
      { threshold, rootMargin }
    );

    nodes.forEach((n) => io.observe(n));
    return () => {
      io.disconnect();
      clearTimeout(failSafe);
    };
  }, [rootRef, selector, threshold, rootMargin]);
}

